    else:
        sign = tz[0]
        if ':' in tz:
            tzh, tzm = tz[1:].split(':')
        elif len(tz) == 4:  # 'snnn'
            tzh, tzm = tz[1], tz[2:4]
        else:
            tzh, tzm = tz[1:3], tz[3:5]
        offset = int(tzm) + int(tzh) * 60
        if sign == '-':
            offset = -offset
        tz = FixedTzOffset(offset, tz)
